'use strict';

// Finds the "Generated by Claude Code" footer that the cloud GitHub route appends to a post after it
// leaves the session, and says how to remove it. The footer is added server side, so the before-tool
// attribution guard cannot see it; this module reads what GitHub sent back instead.
//
// - `footerDecision` is the after-tool (PostToolUse) check. In a governed, guarded or evidence-store
//   checkout (the attribution guard's `repositoryKind`), a GitHub write whose returned body ends with
//   the footer gets a block decision naming the clean edit for kinds the cloud can edit cleanly (issue
//   and pull request comments, issue and pull request bodies), and a note for review comments and
//   review bodies, which only the device sweep can clean. It reads the hook input, the checkout's own
//   `.git`, `.github` and `AGENTS.md` files, and the user's governance decisions file under
//   `~/.ai-agent-toolkit/user-state` (through `repositoryKind`): no git, gh or network call.
// - `stripFooter` and `hasFooter` are shared with the device sweep (toolkit-github-footer-sweep.cjs).

const { githubWrite } = require('../../skills/github-program-reconciler/scripts/programme-refresh-trigger.cjs');

// A rule line, then the italic footer, as the last lines of the body, outside a code block. Tolerates
// CRLF, extra blank lines, up to three leading spaces and a session path after /code. Matched line by
// line, so no regular expression backtracks over the whole body.
const FOOTER_LINE = /^ {0,3}_Generated by \[Claude Code\]\(https:\/\/claude\.ai\/code(?:\/[^)\s]*)?\)_[ \t]*$/;
const RULE_LINE = /^ {0,3}-{3,}[ \t]*$/;
// A code fence: three or more backticks or tildes. It closes only on the same character, at least as
// long as the opening, with nothing after it.
const FENCE_LINE = /^ {0,3}(`{3,}|~{3,})(.*)$/;
const MAX_BODY = 1024 * 1024;
const MAX_PASSES = 5;

// The body split into lines that keep their own line endings.
const splitLines = (body) => body.split(/(?<=\n)/);
const content = (line) => line.replace(/\r?\n$/, '');

// Whether the lines before `end` leave a code fence open.
function insideFence(lines, end) {
  let open = null;
  for (let index = 0; index < end; index += 1) {
    const fence = FENCE_LINE.exec(content(lines[index]));
    if (!fence) continue;
    if (!open) open = fence[1];
    else if (fence[1][0] === open[0] && fence[1].length >= open.length && !fence[2].trim()) open = null;
  }
  return open !== null;
}

// How many lines come before the footer's rule line, or -1 when the body does not end with the footer.
function footerStart(lines) {
  let at = lines.length - 1;
  const skipBlank = () => { while (at >= 0 && !content(lines[at]).trim()) at -= 1; };
  skipBlank();
  if (at < 0 || !FOOTER_LINE.test(content(lines[at]))) return -1;
  at -= 1;
  skipBlank();
  if (at < 0 || !RULE_LINE.test(content(lines[at]))) return -1;
  // Inside an unclosed code fence the footer is quoted code, not a footer.
  if (insideFence(lines, at)) return -1;
  at -= 1;
  skipBlank();
  return at + 1;
}

function hasFooter(body) {
  return typeof body === 'string' && body.length <= MAX_BODY && footerStart(splitLines(body)) >= 0;
}

// The body minus every trailing footer (a cloud edit can add a second one), up to MAX_PASSES.
function stripFooter(body) {
  if (typeof body !== 'string' || body.length > MAX_BODY) return body;
  let lines = splitLines(body);
  for (let pass = 0; pass < MAX_PASSES; pass += 1) {
    const start = footerStart(lines);
    if (start < 0) break;
    lines = lines.slice(0, start);
    if (lines.length) lines[lines.length - 1] = content(lines[lines.length - 1]);
  }
  return lines.join('');
}

const MAX_TEXT = 2 * 1024 * 1024;
const MAX_DEPTH = 6;
const MAX_LINES = 2000;

function parseJson(text) {
  if (typeof text !== 'string' || text.length > MAX_TEXT) return undefined;
  const trimmed = text.trim();
  if (!looksLikeJson(trimmed)) return undefined;
  try { return JSON.parse(trimmed); } catch { return undefined; }
}

// A trimmed text that opens and closes like a JSON object or array.
function looksLikeJson(trimmed) {
  const first = trimmed[0];
  const last = trimmed[trimmed.length - 1];
  return (first === '{' && last === '}') || (first === '[' && last === ']');
}

// Every object in a tool response that carries a string body, with JSON text (MCP content blocks,
// shell stdout, one object per line) parsed on the way.
function postedObjects(value, found = [], depth = 0) {
  if (depth > MAX_DEPTH || value === null || value === undefined) return found;
  if (typeof value === 'string') {
    const parsed = parseJson(value);
    if (parsed !== undefined) return postedObjects(parsed, found, depth + 1);
    if (value.length <= MAX_TEXT && value.includes('\n{')) {
      for (const line of value.split('\n', MAX_LINES)) {
        const trimmed = line.trim();
        if (trimmed[0] !== '{' || trimmed[trimmed.length - 1] !== '}') continue;
        const item = parseJson(trimmed);
        if (item !== undefined) postedObjects(item, found, depth + 1);
      }
    }
    return found;
  }
  if (Array.isArray(value)) {
    for (const item of value.slice(0, 200)) postedObjects(item, found, depth + 1);
    return found;
  }
  if (typeof value === 'object') {
    if (typeof value.body === 'string') found.push(value);
    for (const [key, item] of Object.entries(value)) {
      if (key !== 'body') postedObjects(item, found, depth + 1);
    }
  }
  return found;
}

// The connector tools that post a body, and what they post when the html_url does not say.
const TOOL_KINDS = {
  add_issue_comment: 'issue_comment', update_issue_comment: 'issue_comment',
  create_pull_request: 'pull_request', update_pull_request: 'pull_request',
  issue_write: 'issue', create_issue: 'issue', update_issue: 'issue',
  add_reply_to_pull_request_comment: 'review_comment', add_comment_to_pending_review: 'review_comment',
  pull_request_review_write: 'review', create_and_submit_pull_request_review: 'review', submit_pending_pull_request_review: 'review',
};

function describe(object, toolKind, input) {
  const url = typeof object.html_url === 'string' ? object.html_url : (typeof object.url === 'string' ? object.url : '');
  const match = /^https:\/\/github\.com\/([\w.-]+)\/([\w.-]+)\/(issues|pull)\/(\d+)(?:#(issuecomment|discussion_r|pullrequestreview)-?(\d+))?\/?$/.exec(url);
  const target = { url: url || null, repository: null, number: null, id: null, kind: toolKind || null };
  if (match) {
    target.repository = `${match[1]}/${match[2]}`;
    target.number = Number(match[4]);
    target.id = match[6] ? Number(match[6]) : null;
    target.kind = match[5] === 'issuecomment' ? 'issue_comment'
      : match[5] === 'discussion_r' ? 'review_comment'
        : match[5] === 'pullrequestreview' ? 'review'
          : match[3] === 'pull' ? 'pull_request' : 'issue';
  }
  const { owner, repo } = input?.tool_input || {};
  if (!target.repository && typeof owner === 'string' && typeof repo === 'string' && owner && repo) target.repository = `${owner}/${repo}`;
  if (target.id === null && (target.kind === 'issue_comment' || target.kind === 'review_comment' || target.kind === 'review') && Number.isInteger(object.id)) target.id = object.id;
  if (target.number === null && Number.isInteger(object.number)) target.number = object.number;
  target.empty = !stripFooter(object.body).trim();
  return target;
}

const CLEAN_KINDS = new Set(['issue_comment', 'pull_request', 'issue']);
const EDIT_TOOLS = new Set(['update_issue_comment', 'update_pull_request', 'update_issue']);
// Shell writes that post a body: gh issue or pr create, comment, edit or review, and a gh api call
// that is not a DELETE (or a GET). Each gh api piece runs to the next shell separator, and its method
// is read from that piece alone, as the programme refresh trigger does, so a long command stays linear.
const GH_API = /\bgh(?:\.exe)?\s+api\b[^\r\n;&|]*/gi;
const GH_METHOD = /\s(?:-X|--method)[\s=]*['"]?([A-Z]+)\b/i;
const GH_POST = /\bgh(?:\.exe)?\s+(?:issue|pr)\s+(?:create|comment|edit|review)\b/i;
// gh issue or pr close pieces, each read on its own for a comment flag, so the check stays linear.
const GH_CLOSE = /\bgh(?:\.exe)?\s+(?:issue|pr)\s+close\b[^\r\n;&|]*/gi;
const closesWithComment = (command) => [...command.matchAll(GH_CLOSE)].some(([piece]) => /\s(?:--comment|-c)\b/.test(piece));
const GH_EDIT = /\bgh(?:\.exe)?\s+(?:issue|pr)\s+edit\b/i;
// Any gh write whose response is worth reading for a footer.
const SHELL_GH = /\bgh(?:\.exe)?\s+(?:api|issue|pr)\b/i;

function ghApiMethods(command) {
  return [...command.matchAll(GH_API)].map(([piece]) => (GH_METHOD.exec(piece)?.[1] || 'POST').toUpperCase());
}
function shellPosts(command) {
  return GH_POST.test(command) || closesWithComment(command) || ghApiMethods(command).some((method) => method !== 'DELETE' && method !== 'GET');
}
// Shell edits: gh api with PATCH or PUT, and gh issue or pr edit.
function shellEdit(command) {
  return GH_EDIT.test(command) || ghApiMethods(command).some((method) => method === 'PATCH' || method === 'PUT');
}

function cleanEdit(target) {
  const [owner, repo] = String(target.repository || 'OWNER/REPO').split('/');
  const where = `owner ${owner}, repo ${repo}`;
  if (target.kind === 'issue_comment') return `GitHub connector \`update_issue_comment\` (${where}, comment_id ${target.id ?? '?'})`;
  if (target.kind === 'pull_request') return `GitHub connector \`update_pull_request\` (${where}, pullNumber ${target.number ?? '?'})`;
  return `GitHub connector \`issue_write\` with method update (${where}, issue_number ${target.number ?? '?'})`;
}

const label = (target) => target.url || `${target.kind} in ${target.repository || 'this repository'}`;

// Whether the checkout a folder is in is governed, guarded or an evidence store.
function guardedCheckout(folder) {
  if (typeof folder !== 'string' || !folder) return false;
  try {
    const kind = require('./toolkit-attribution-guard.cjs').repositoryKind(folder, new Map());
    return Boolean(kind.checked || kind.store);
  } catch { return false; }
}

const SWEEP = 'node repo/scripts/toolkit-github-footer-sweep.cjs --repo <owner/name> --apply';

function shellCommand(input) {
  const command = input?.tool_input?.command ?? input?.tool_input?.cmd;
  return Array.isArray(command) ? command.join(' ') : (typeof command === 'string' ? command : '');
}

// The after-tool decision: {} when there is nothing to do, else a Claude Code PostToolUse output.
function footerDecision(input, deps = {}) {
  if (!input || typeof input !== 'object' || input.hook_event_name !== 'PostToolUse') return {};
  if (!githubWrite(input)) return {};
  const name = String(input.tool_name || '');
  const tool = /^mcp__.+__([^_].*)$/.exec(name)?.[1] || '';
  // Of the connector writes, only those that post a body; others (sub-issue links, merges, file
  // pushes) may echo older posts that this write did not make.
  if (tool && !TOOL_KINDS[tool]) return {};
  const command = tool ? '' : shellCommand(input);
  if (!tool && !SHELL_GH.test(command)) return {};
  const guarded = deps.guarded || guardedCheckout;
  if (!guarded(input.cwd)) return {};
  const toolKind = TOOL_KINDS[tool] || null;
  const objects = postedObjects(input.tool_response);
  const footed = objects.filter((object) => hasFooter(object.body)).map((object) => describe(object, toolKind, input));
  const unique = [...new Map(footed.map((target) => [label(target), target])).values()];
  // An edit that came back with the footer again would only loop, and a comment that is only the
  // footer cannot be emptied: leave both to the device sweep.
  const edit = EDIT_TOOLS.has(tool) || (tool === 'issue_write' && input.tool_input?.method === 'update') || (!tool && shellEdit(command));
  const fixable = (target) => !edit && CLEAN_KINDS.has(target.kind) && !(target.empty && target.kind === 'issue_comment');
  const strippable = unique.filter(fixable);
  const deviceOnly = unique.filter((target) => !fixable(target));
  if (strippable.length) {
    const steps = strippable.map((target) => `- ${label(target)}: call ${cleanEdit(target)} with the same body minus the "Generated by Claude Code" footer, then read it back.`);
    const extra = deviceOnly.length ? ` These cannot be cleaned from the cloud; list them in your report for the device sweep (\`${SWEEP}\`): ${deviceOnly.map(label).join(', ')}.` : '';
    return { decision: 'block', reason: `GitHub added the "Generated by Claude Code" footer to what you just posted. Toolkit rules forbid it. Remove it now:\n${steps.join('\n')}${extra}` };
  }
  if (deviceOnly.length) {
    return { hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: `GitHub added the "Generated by Claude Code" footer to ${deviceOnly.map(label).join(', ')}, and it cannot be cleaned from the cloud: list it in your report; the device sweep (\`${SWEEP}\`) cleans it.` } };
  }
  // A cloud write whose response shows no body (a minimal connector response, or gh printing only a
  // URL) cannot be checked here: ask for a read-back.
  const cloud = (deps.env || process.env).CLAUDE_CODE_REMOTE === 'true';
  if (cloud && objects.length === 0 && (tool || shellPosts(command))) {
    return { hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: 'The cloud GitHub route may have added a "Generated by Claude Code" footer to this post, and the response does not show the body. Read it back; if the footer is there, remove it with the matching connector update call (update_issue_comment, update_pull_request or issue_write), or list a review comment for the device sweep.' } };
  }
  return {};
}

module.exports = Object.freeze({ hasFooter, stripFooter, postedObjects, describe, guardedCheckout, footerDecision, SWEEP });
